function runSigmaBtc() {
const p = parameters ?? {};
const price = Number(currentPrice);
const series = Array.isArray(prices)
  ? prices.map(x => Number(typeof x === 'object' ? (x.close ?? x.price ?? x.value) : x)).filter(Number.isFinite)
  : [];

const cfg = {
  fastEma: Number(p.fastEma ?? 20),
  slowEma: Number(p.slowEma ?? 50),
  breakoutLookback: Number(p.breakoutLookback ?? 20),
  meanReversionLookback: Number(p.meanReversionLookback ?? 20),
