function finiteWindow(n) { return Math.max(2, Math.min(Math.floor(n), series.length)); }
function sma(a, n) {
  n = finiteWindow(n); if (a.length < n) return NaN;
  let s = 0; for (let i = a.length - n; i < a.length; i++) s += a[i]; return s / n;
}
function ema(a, n) {
  n = Math.max(2, Math.floor(n)); if (a.length < n) return NaN;
  let e = a.slice(0, n).reduce((x, y) => x + y, 0) / n;
  const k = 2 / (n + 1);
  for (let i = n; i < a.length; i++) e = a[i] * k + e * (1 - k);
  return e;
}
